import java.util.*;
public class E210 {
    static class User {
        int id;
        User(int id) { this.id = id; }
        @Override public boolean equals(Object o) {
            return o instanceof User u && id == u.id;
        }
        @Override public int hashCode() { return id; }
    }
    static class BadUser {
        int id;
        BadUser(int id) { this.id = id; }
        @Override public boolean equals(Object o) {
            return o instanceof BadUser u && id == u.id;
        }
    }
    public static void main(String[] args) {
        Map<User, String> good = new HashMap<>();
        good.put(new User(1), "alice");
        System.out.println("good get: " + good.get(new User(1)));
        Map<BadUser, String> bad = new HashMap<>();
        bad.put(new BadUser(1), "bob");
        System.out.println("bad get: " + bad.get(new BadUser(1)));
    }
}
